        async function memeDBPut(k,v){const d=await memeOpenDB();return new Promise((r,j)=>{const t=d.transaction(MEME_DB_STORE,'readwrite');t.objectStore(MEME_DB_STORE).put(v,k);t.oncomplete=()=>{d.close();r();};t.onerror=()=>{d.close();j(t.error);};});}
        async function memeDBGet(k){const d=await memeOpenDB();return new Promise((r,j)=>{const t=d.transaction(MEME_DB_STORE,'readonly'),q=t.objectStore(MEME_DB_STORE).get(k);q.onsuccess=()=>r(q.result);q.onerror=()=>j(q.error);t.oncomplete=()=>d.close();});}
