        function memeB64Buffer(id){const raw=atob(MEME_AUDIO_BASE64[id]),u=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)u[i]=raw.charCodeAt(i);return u.buffer;}
        function memeMap(){const map={};MEME_ORIGINALS.forEach(o=>{const m=MEME_CONFIG.meta[o.id]||{};map[o.id]={...o,name:m.name||o.name,customAudio:!!m.customAudio};});Object.keys(MEME_CONFIG.meta).forEach(id=>{const m=MEME_CONFIG.meta[id];if(m&&m.custom)map[id]={id,name:m.name||'Meme',icon:m.icon||'🔊',gain:5,custom:true};});return map;}
