        function memeRestoreState(raw){const x=JSON.parse(raw);MEME_CONFIG.order=x.order;MEME_CONFIG.meta=x.meta;MEME_CONFIG.style=x.style;MEME_CONFIG.locked=x.locked;memeSave();}
        function memePushHistory(){const raw=memeCloneState();if(memeHistory[memeHistoryIndex]===raw)return;memeHistory=memeHistory.slice(0,memeHistoryIndex+1);memeHistory.push(raw);memeHistoryIndex=memeHistory.length-1;if(memeHistory.length>60){memeHistory.shift();memeHistoryIndex--;}}
        function memeUndo(){if(memeHistoryIndex<=0)return;memeHistoryIndex--;memeRestoreState(memeHistory[memeHistoryIndex]);renderMemeBoard();refreshEditor();}
        function memeUndoAll(){if(!memeHistory.length)return;memeRestoreState(memeHistory[0]);memeHistory=[memeHistory[0]];memeHistoryIndex=0;renderMemeBoard();refreshEditor();}
        async function memeDecode(id){if(MEME_AUDIO_CACHE[id])return MEME_AUDIO_CACHE[id];if(!_ctx)throw new Error('AudioContext chưa sẵn sàng');const item=memeMap()[id];let raw;if(item?.custom)raw=await memeDBGet(id);else if(item?.customAudio)raw=await memeDBGet('override:'+id);else raw=memeB64Buffer(id);if(!raw)throw new Error('Không tìm thấy âm thanh');const b=await _ctx.decodeAudioData((raw instanceof ArrayBuffer?raw:raw.buffer).slice(0));MEME_AUDIO_CACHE[id]=b;return b;}
        async function playMeme(id){try{if(!await ensureEngineReady()||!_ctx)return;if(_ctx.state==='suspended')await _ctx.resume();stopCurrentAudio();const item=memeMap()[id],src=_ctx.createBufferSource(),g=_ctx.createGain();src.buffer=await memeDecode(id);g.gain.value=item.gain||5;src.connect(g);g.connect(_mp3GainNode);src.start(0);activeAudioSource=src;src.onended=()=>{if(activeAudioSource===src)activeAudioSource=null;};}catch(e){console.error('[LeneFX] meme failed',e);alert('❌ Không phát được meme!\n'+(e.message||e));}}
        // --- TAP CONTROLS (optional per-tap pause/restart overlay; MEME_CONFIG.tapControls) ---
        // AudioBufferSourceNode has no native pause, so "pausing" means: remember how many
        // seconds of the buffer had played (offset), fully stop the node, and on resume start
        // a brand-new node at that offset. Calling stop() fires onended same as a natural
        // finish, so every manual stop here first clears onended so that our "hide overlay,
        // clear state" cleanup only ever runs for a real natural end, never for a pause/restart.
        function tapResetIdleTimer(cell){
            if(cell._tapHideTimer)clearTimeout(cell._tapHideTimer);
            cell._tapHideTimer=setTimeout(()=>{tapHideOverlay(cell);},5000);
        }
        function tapShowOverlay(cell){
            const btn=cell.querySelector('.avt-sfx-btn');
            if(!btn)return;
            let ov=btn.querySelector('.meme-tap-overlay');
            if(!ov){
                ov=document.createElement('div');
                ov.className='meme-tap-overlay';
                ov.innerHTML='<button type="button" class="tap-ico tap-restart" title="Phát lại">↺</button><button type="button" class="tap-ico tap-pause" title="Tạm dừng">⏸️</button>';
                btn.appendChild(ov);
                ov.querySelector('.tap-restart').addEventListener('click',e=>{e.stopPropagation();tapDoRestart();tapResetIdleTimer(cell);});
                ov.querySelector('.tap-pause').addEventListener('click',e=>{e.stopPropagation();tapTogglePause();tapResetIdleTimer(cell);});
                // Keep the drag-reorder pointer logic on the button underneath from ever seeing
                // these taps — a tap on a tiny overlay icon should never be mistaken for a drag.
                ['pointerdown','pointerup','pointermove'].forEach(t=>ov.addEventListener(t,e=>e.stopPropagation()));
            }
            ov.querySelector('.tap-pause').textContent='⏸️';
            tapResetIdleTimer(cell);
        }
        async function tapStartFresh(id,cell){
            try{
                if(!await ensureEngineReady()||!_ctx)return;
                if(_ctx.state==='suspended')await _ctx.resume();
                stopCurrentAudio();
                const item=memeMap()[id];
                const buffer=await memeDecode(id);
                const gain=_ctx.createGain();
                gain.gain.value=item.gain||5;
                gain.connect(_mp3GainNode);
                const source=_ctx.createBufferSource();
                source.buffer=buffer;
                source.connect(gain);
                source.start(0,0);
                tapPlayback={id,buffer,gain,source,startedCtxTime:_ctx.currentTime,offset:0,paused:false,cellEl:cell};
                activeAudioSource=source;
                source.onended=()=>{
                    if(activeAudioSource===source)activeAudioSource=null;
                    if(tapPlayback&&tapPlayback.source===source){tapHideOverlay(cell);tapPlayback=null;}
                };
                tapShowOverlay(cell);
            }catch(e){console.error('[LeneFX] tap meme failed',e);alert('❌ Không phát được meme!\n'+(e.message||e));}
        }
        function tapTogglePause(){
            if(!tapPlayback)return;
            const cellEl=tapPlayback.cellEl;
            const pauseIco=cellEl&&cellEl.querySelector('.meme-tap-overlay .tap-pause');
            if(!tapPlayback.paused){
                const elapsed=_ctx.currentTime-tapPlayback.startedCtxTime;
                tapPlayback.offset=Math.min(tapPlayback.buffer.duration,tapPlayback.offset+elapsed);
                const src=tapPlayback.source;
                if(src){src.onended=null;try{src.stop();}catch(e){}try{src.disconnect();}catch(e){}}
                tapPlayback.source=null;
                tapPlayback.paused=true;
                if(activeAudioSource===src)activeAudioSource=null;
                if(pauseIco)pauseIco.textContent='▶️';
            }else{
                let off=tapPlayback.offset;
                if(off>=tapPlayback.buffer.duration)off=0;
                const source=_ctx.createBufferSource();
                source.buffer=tapPlayback.buffer;
                source.connect(tapPlayback.gain);
                source.start(0,off);
                tapPlayback.source=source;
                tapPlayback.startedCtxTime=_ctx.currentTime;
                tapPlayback.paused=false;
                activeAudioSource=source;
                source.onended=()=>{
                    if(activeAudioSource===source)activeAudioSource=null;
                    if(tapPlayback&&tapPlayback.source===source){tapHideOverlay(cellEl);tapPlayback=null;}
                };
                if(pauseIco)pauseIco.textContent='⏸️';
            }
        }
