        async function memeGetMediaURL(id){const m=MEME_CONFIG.meta[id]?.media;if(!m)return '';try{const data=await memeDBGet('media:'+id);if(!data)return '';if(MEME_MEDIA_URLS[id])URL.revokeObjectURL(MEME_MEDIA_URLS[id]);const blob=data instanceof Blob?data:new Blob([data],{type:m.type||'application/octet-stream'});MEME_MEDIA_URLS[id]=URL.createObjectURL(blob);return MEME_MEDIA_URLS[id];}catch(e){return '';}}
        async function renderMemeBoard(){
            const grid=menu.querySelector('#avt-meme-grid');
            if(!grid)return;
            const map=memeMap();
            grid.innerHTML='';
            const ids=[];
            MEME_CONFIG.order.forEach(id=>{if(map[id]&&!ids.includes(id))ids.push(id);});
            Object.keys(map).forEach(id=>{if(!ids.includes(id))ids.push(id);});
            MEME_CONFIG.order=ids;
            memeSave();
            for(const id of ids){
                const item=map[id],cell=document.createElement('div');
                cell.className='avt-meme-cell';
                cell.dataset.id=id;
                const b=document.createElement('button');
                b.type='button';b.className='avt-sfx-btn';b.dataset.key=id;
                const st=memeStyle(id);
                // The CELL claims the real layout space (a % width in the flex-wrap grid);
                // the BUTTON just fills 100% of that cell. Before, only the button's own
                // width changed while the cell stayed a fixed 1fr grid column — shrinking
                // left a hollow gap, growing overflowed/overlapped the next column.
                cell.style.width='calc('+(50*Math.max(0.1,st.width))+'% - 2.5px)';
                b.style.width='100%';
                b.style.height=Math.max(30,36*st.height)+'px';
                b.style.borderRadius=(st.borderRadius/100*50)+'%';
                b.style.color=st.color;
                b.style.fontSize=(9*st.fontSize)+'px';
                b.style.fontFamily=GLOBAL_FONT_ON?GLOBAL_FONT_FAMILY:(st.fontFamily||'system-ui, -apple-system, sans-serif');
                b.innerHTML='<span class="meme-title">'+(item.icon||'🔊')+' '+escapeHtml(item.name)+'</span>';
                cell.appendChild(b);
                grid.appendChild(cell);

                const media=await memeGetMediaURL(id);
                if(media){
                    const mediaMeta=MEME_CONFIG.meta[id].media;
                    const rotation=mediaMeta.rotation||0;
                    if(mediaMeta.type?.startsWith('video/')){
                        const v=document.createElement('video');
                        v.className='meme-media';
                        v.src=media;
                        // Setting autoplay=false when paused (instead of starting playback and
                        // racing to pause() it a frame later) avoids the flash-of-playing bug —
                        // the video simply never starts until the user un-pauses it.
                        v.autoplay=!mediaMeta.paused;
                        v.muted=!mediaMeta.audioOn;
                        v.loop=true;
                        v.playsInline=true;
                        v.preload='auto';
                        b.prepend(v);
                        applyMediaTransform(v,b,rotation,true);
                        if(!mediaMeta.paused)v.play().catch(()=>{});
                    }else{
                        const im=document.createElement('img');
                        im.className='meme-media';
                        im.src=media;
                        b.prepend(im);
                        applyMediaTransform(im,b,rotation,false);
                    }
                }

                b.addEventListener('click',e=>{if(memeDraggingId)return;if(memeEditor&&memeEditor.style.display!=='none')return;if(MEME_CONFIG.tapControls){tapStartFresh(id,cell);}else{playMeme(id);}});
                attachMemeDrag(cell,b);
            }
            menu.querySelector('#avt-meme-count').textContent=ids.length+' MEME';
            const lock=menu.querySelector('#avt-meme-lock');
            lock.textContent='🔒 KHÓA MEME GỐC: '+(MEME_CONFIG.locked?'ON':'OFF');
            lock.classList.toggle('active',MEME_CONFIG.locked);
        }

        // Sizes/rotates a media element (img or video) so a 90°/270° rotation still fits
        // fully inside its button's box (dimension-swap trick). Video fills the box
        // completely (object-fit:cover, cropping overflow) per request; images keep
        // object-fit:contain so nothing gets cropped out of frame.
        function applyMediaTransform(mediaEl,btnEl,rotation,isVideo){
            const apply=()=>{
                const w=btnEl.clientWidth,h=btnEl.clientHeight;
                if(!w||!h)return;
                if(rotation===90||rotation===270){
                    mediaEl.style.width=h+'px';
                    mediaEl.style.height=w+'px';
                    mediaEl.style.left=((w-h)/2)+'px';
                    mediaEl.style.top=((h-w)/2)+'px';
                }else{
                    mediaEl.style.width='100%';
                    mediaEl.style.height='100%';
                    mediaEl.style.left='0';
                    mediaEl.style.top='0';
                }
                mediaEl.style.transform=rotation?('rotate('+rotation+'deg)'):'';
                mediaEl.style.objectFit=isVideo?'cover':'contain';
            };
            requestAnimationFrame(apply);
        }

        function escapeHtml(x){return String(x).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}

        function attachMemeDrag(cell,b){
            let down=null,moved=false;
            const onDown=e=>{
                if(memeEditor&&memeEditor.style.display!=='none')return;
                down={x:e.clientX,y:e.clientY,id:cell.dataset.id,pid:e.pointerId};
                moved=false;memeDragStart=down;
                try{b.setPointerCapture(e.pointerId);}catch(_){}
            };
            const onMove=e=>{
                if(!down)return;
                const d=Math.hypot(e.clientX-down.x,e.clientY-down.y);
                if(d>7&&!moved){moved=true;memeDraggingId=down.id;cell.classList.add('dragging');}
                if(!moved)return;
                const over=document.elementFromPoint(e.clientX,e.clientY)?.closest('.avt-meme-cell');
                document.querySelectorAll('.avt-meme-cell').forEach(x=>x.classList.remove('drop-target','drop-before','drop-after'));
                if(over&&over!==cell){
                    const r=over.getBoundingClientRect();
                    over.classList.add('drop-target');
                    over.classList.add(e.clientY<r.top+r.height/2?'drop-before':'drop-after');
                    memeDropTarget=over.dataset.id;
                }
            };
            const onUp=e=>{
                if(!down)return;
                const id=down.id;
                const over=document.elementFromPoint(e.clientX,e.clientY)?.closest('.avt-meme-cell');
                if(moved&&over&&over!==cell){
                    const item=memeMap()[id];
                    const overItem=memeMap()[over.dataset.id];
                    // Lock only ever blocks POSITION changes: moving an original meme itself,
                    // or dropping any other meme onto an original meme's slot. It never blocks
                    // rename / change sound / delete file — those are handled in the editor.
                    const positionLocked=MEME_CONFIG.locked&&(item?.original||overItem?.original);
                    if(!positionLocked){
                        const from=MEME_CONFIG.order.indexOf(id),to0=MEME_CONFIG.order.indexOf(over.dataset.id);
                        let to=to0;
                        const r=over.getBoundingClientRect();
                        if(e.clientY>=r.top+r.height/2)to=to0+1;
                        const x=MEME_CONFIG.order.splice(from,1)[0];
                        if(to>from)to--;
                        MEME_CONFIG.order.splice(Math.max(0,Math.min(to,MEME_CONFIG.order.length)),0,x);
                        memePushHistory();memeSave();renderMemeBoard();
                    }
                }
                cell.classList.remove('dragging');
                document.querySelectorAll('.avt-meme-cell').forEach(x=>x.classList.remove('drop-target','drop-before','drop-after'));
                memeDraggingId=null;memeDropTarget=null;down=null;
            };
            b.addEventListener('pointerdown',onDown);
            b.addEventListener('pointermove',onMove);
            b.addEventListener('pointerup',onUp);
            b.addEventListener('pointercancel',onUp);
        }

        function memeSetEditorId(id){
            memeEditorId=id||null;
            try{if(memeEditorId)localStorage.setItem('LENE_MEME_LAST_ID',memeEditorId);}catch(e){}
        }

        // Sets an opacity slider + typeable number readout pair (used for both the
        // background-opacity and content-opacity controls, on both panels).
        function wireOpacityPair(rangeEl,valEl,storageKey,applyFn,defaultV){
            const setV=(v)=>{
                v=Math.max(1,Math.min(100,Math.round(v)||defaultV));
                rangeEl.value=v;valEl.textContent=v;
                applyFn(v/100);
                try{localStorage.setItem(storageKey,v);}catch(e){}
            };
            rangeEl.oninput=()=>setV(rangeEl.value);
            valEl.addEventListener('blur',()=>setV(parseInt(valEl.textContent,10)));
            valEl.addEventListener('keydown',(e)=>{if(e.key==='Enter'){e.preventDefault();valEl.blur();}});
            setV(parseInt(localStorage.getItem(storageKey),10)||defaultV);
        }

