            // Apply saved editor size
            {let esz={w:380};try{esz=JSON.parse(localStorage.getItem('LENE_MENU_EDITOR_SIZE')||'{"w":380}');}catch(e){}memeEditor.style.width=Math.min(esz.w,window.innerWidth-20)+'px';}
            memeEditor.querySelector('#ed-resize-btn').onclick=()=>{const p=memeEditor.querySelector('#ed-resize-panel');if(p)p.style.display=p.style.display==='none'?'block':'none';};
            const edRw=memeEditor.querySelector('#ed-rw');
            if(edRw)edRw.oninput=()=>{const v=parseInt(edRw.value);const el=memeEditor.querySelector('#ed-rw-v');if(el)el.textContent=v;memeEditor.style.width=Math.min(v,window.innerWidth-20)+'px';};
